//! Std-only smoke run of the `go1_compressed_lowcmd` libFuzzer target
//! (`fuzz/fuzz_targets/`): the same harness
//! (`fuzz/harness/go1_compressed_lowcmd.rs`, included by path) driven by the
//! deterministic mutator in `fuzz/harness/smoke.rs` over the committed seed
//! corpus. See `fuzz/README.md`. The seeds are (re)generated by
//! `regenerate_seeds` (run with `--ignored`).

#[path = "../../../fuzz/harness/go1_compressed_lowcmd.rs"]
mod go1_compressed_lowcmd;
#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;

use robodr_firewall_gw::legacy;

const DIR: &str = env!("CARGO_MANIFEST_DIR");

fn seeds() -> Vec<(&'static str, Vec<u8>)> {
    let mut motors = vec![(0u8, [0f32; 5]); 20];
    for (i, m) in motors.iter_mut().enumerate().take(12) {
        *m = (0x0A, [0.1 * i as f32, 0.0, 1.5, 20.0, 1.0]);
    }
    let good = legacy::build_low_compressed(&motors);
    let mut bad_crc = good.clone();
    bad_crc[40] ^= 0x10;
    let mut off = good.clone();
    off[legacy::LOWC_BMS_AT] = 0xA5;
    legacy::seal(&mut off);
    vec![
        ("seed-go1-compressed.bin", good),
        ("seed-go1-compressed-badcrc.bin", bad_crc),
        ("seed-go1-compressed-bms-off.bin", off),
        ("seed-go1-compressed-template.bin", legacy::lowc_template()),
    ]
}

#[test]
#[ignore = "regenerates fuzz/corpus/go1_compressed_lowcmd"]
fn regenerate_seeds() {
    let dir = smoke::corpus_dir(DIR, "go1_compressed_lowcmd");
    std::fs::create_dir_all(&dir).unwrap();
    for (name, bytes) in seeds() {
        std::fs::write(dir.join(name), bytes).unwrap();
    }
}

#[test]
fn committed_seeds_match_the_generator() {
    let committed = smoke::corpus(DIR, "go1_compressed_lowcmd");
    for (_, s) in seeds() {
        assert!(
            committed.contains(&s),
            "a seed changed: run regenerate_seeds"
        );
    }
}

#[test]
fn go1_compressed_lowcmd_smoke() {
    let mut seeds: Vec<Vec<u8>> = smoke::corpus(DIR, "go1_compressed_lowcmd");
    seeds.extend(self::seeds().into_iter().map(|(_, s)| s));
    smoke::run(
        "go1_compressed_lowcmd",
        &seeds,
        0x601c_0614,
        &go1_compressed_lowcmd::run,
    );
}
